const METAL = [[1, 1, 1], [1.51, 0.6, 0.8], [2.33, 0.5, 0.6], [3.42, 0.35, 0.45], [4.7, 0.25, 0.3]] as const;

type Opt = Partial<Layer>;
/** A voice-like sound: a buzzy tone through band-pass "mouth" filters [from Hz, to Hz, level]. */
const voiced = (f: number, f2: number, d: number, mouth: ReadonlyArray<readonly [number, number, number]>, o: Opt = {}): Layer[] =>
  mouth.map(([fc, fc2, v]) => ({ w: 'saw' as const, f, f2, d, ft: 'bp' as const, fc, fc2, q: 4, env: [0.02, 0.05, 0.85, 0.07] as const, v, ...o }));
/** A water drop or bubble: a short sine chirping upward. */
const blub = (f: number, d = 0.05, o: Opt = {}): Layer => ({ w: 'sine', f, f2: f * 2.4, d, c: 2, env: [0.003, d, 0, 0.02], ...o });

